"use client";

import React, {createContext,useContext,useEffect,useRef,useState} from "react";
import {flushSync} from "react-dom";
import {ArrowRight,ArrowUpRight,BookOpen,Check,CheckCheck,ChevronRight,ClipboardCheck,Code2,Download,FileCode2,FileText,FlaskConical,GitBranch,GraduationCap,HelpCircle,History,Layers3,LockKeyhole,MessageSquare,RotateCcw,ShieldCheck,SlidersHorizontal,Terminal,TriangleAlert,Workflow} from "lucide-react";
import {Button} from "@/components/ui/button";
import {Tabs,TabsContent,TabsList,TabsTrigger} from "@/components/ui/tabs";
import {Sheet,SheetContent,SheetDescription,SheetHeader,SheetTitle} from "@/components/ui/sheet";
import {Checkbox} from "@/components/ui/checkbox";
import {Select,SelectContent,SelectItem,SelectTrigger,SelectValue} from "@/components/ui/select";
import {Progress} from "@/components/ui/progress";
import {Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from "@/components/ui/table";
import {AlertDialog,AlertDialogAction,AlertDialogCancel,AlertDialogContent,AlertDialogDescription,AlertDialogFooter,AlertDialogHeader,AlertDialogTitle,AlertDialogTrigger} from "@/components/ui/alert-dialog";
import {Sidebar,SidebarContent,SidebarFooter,SidebarGroup,SidebarGroupLabel,SidebarHeader,SidebarInset,SidebarMenu,SidebarMenuButton,SidebarMenuItem,SidebarProvider,SidebarTrigger,useSidebar} from "@/components/ui/sidebar";
import {activeAttempt,authorErrors,initialState,maxHelp,reviewSnapshot,snapshotDraft,sourceFor,sourcePaths,transition,validateSelection} from "@/lib/workflow";
